create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,domain text,public_key text unique not null default('proj_'||encode(gen_random_bytes(9),'hex')),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_settings(id uuid primary key default gen_random_uuid(),project_id uuid unique not null references public.projects(id) on delete cascade,validation_mode text not null default 'submit',show_error_summary boolean not null default true,focus_error_summary boolean not null default true,disable_native_validation boolean not null default true,debug_mode boolean not null default false,messages jsonb not null default '{}'::jsonb);
create table public.form_configs(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,form_identifier text not null,display_name text,configuration jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,form_identifier));
create table public.scan_results(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,form_identifier text,error_count integer not null default 0,warning_count integer not null default 0,passed_count integer not null default 0,results jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create table public.validation_events(id bigint generated always as identity primary key,project_id uuid not null references public.projects(id) on delete cascade,form_identifier text,field_type text,rule_name text,event_type text not null,created_at timestamptz not null default now());
create index projects_user_id_idx on public.projects(user_id);create index scans_project_id_idx on public.scan_results(project_id);create index events_project_created_idx on public.validation_events(project_id,created_at desc);
alter table public.profiles enable row level security;alter table public.projects enable row level security;alter table public.project_settings enable row level security;alter table public.form_configs enable row level security;alter table public.scan_results enable row level security;alter table public.validation_events enable row level security;
create policy "profiles own row" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "projects owned" on public.projects for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "settings through project" on public.project_settings for all using(exists(select 1 from public.projects p where p.id=project_id and p.user_id=auth.uid())) with check(exists(select 1 from public.projects p where p.id=project_id and p.user_id=auth.uid()));
create policy "forms through project" on public.form_configs for all using(exists(select 1 from public.projects p where p.id=project_id and p.user_id=auth.uid())) with check(exists(select 1 from public.projects p where p.id=project_id and p.user_id=auth.uid()));
create policy "scans through project" on public.scan_results for all using(exists(select 1 from public.projects p where p.id=project_id and p.user_id=auth.uid())) with check(exists(select 1 from public.projects p where p.id=project_id and p.user_id=auth.uid()));
create policy "events visible to owner" on public.validation_events for select using(exists(select 1 from public.projects p where p.id=project_id and p.user_id=auth.uid()));
create view public.public_project_configs with(security_invoker=true) as select p.public_key,p.is_active,s.validation_mode,s.show_error_summary,s.focus_error_summary,s.disable_native_validation,s.messages from public.projects p join public.project_settings s on s.project_id=p.id;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',''));return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
